 final WorkoutEstimateService estimates=mock(WorkoutEstimateService.class);final CurrentUserService current=mock(CurrentUserService.class);final ExerciseEntryV2Service entries=mock(ExerciseEntryV2Service.class);
 final org.springframework.test.web.servlet.MockMvc mvc=MockMvcBuilders.standaloneSetup(new ExerciseEntryV2Controller(estimates,current,entries,mock(WorkoutCorrectionPreviewService.class),mock(WorkoutMutationService.class),mock(ExerciseEntryReadService.class))).setControllerAdvice(new ApiExceptionHandler()).build();
 final UUID id=UUID.fromString("22222222-2222-4222-8222-222222222222");
 String body(){return "{\"recordDate\":\"2020-01-02\",\"zone\":\"Australia/Sydney\",\"source\":\"MANUAL\",\"entry\":{\"kind\":\"QUICK\",\"clientEntryId\":\""+id+"\",\"period\":{\"clientEntryId\":\""+id+"\",\"periodKind\":\"STRENGTH\",\"optionId\":\"201\",\"durationMinutes\":50,\"equipmentDetails\":{},\"movements\":[]}}}";}
 @Test void previewUsesOnlyCurrentOwnerAndReturnsPublicEstimateFields()throws Exception{var user=new User();user.setId(42L);when(current.requireGeneralUser(null)).thenReturn(user);var energy=new BigDecimal("854.233");when(estimates.previewNew(eq(42L),any())).thenReturn(new WorkoutEstimateService.Response(List.of(new WorkoutEstimateService.PeriodPreview(id,new BigDecimal("50"),"AVAILABLE",energy,"a".repeat(64),null)),new BigDecimal("50"),energy,false,"b".repeat(64),"c".repeat(64)));mvc.perform(post("/api/v2/exercise/preview").param("owner","99").contentType(MediaType.APPLICATION_JSON).content(body())).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.knownEnergyKj").value(854.233)).andExpect(jsonPath("$.periods[0].unavailableReason").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.periods[0].metUsed").doesNotExist()).andExpect(jsonPath("$.periods[0].weightKgUsed").doesNotExist());var input=org.mockito.ArgumentCaptor.forClass(ExerciseEntryInputs.PreviewRequest.class);verify(estimates).previewNew(eq(42L),input.capture());org.junit.jupiter.api.Assertions.assertInstanceOf(ExerciseEntryInputs.QuickPreview.class,input.getValue().entry());}
 @Test void clientAuthorityStringNumbersAndWrongSchemaFingerprintNeverReachEstimate()throws Exception{for(String input:List.of(body().replace("\"durationMinutes\":50","\"durationMinutes\":\"50\""),body().replace("\"optionId\":\"201\"","\"optionId\":201"),body().replace("\"durationMinutes\":50","\"durationMinutes\":50,\"met\":99"),body().replace("\"durationMinutes\":50","\"durationMinutes\":50,\"calculationFingerprint\":\""+"a".repeat(64)+"\""),body().replace("\"source\":\"MANUAL\"","\"source\":0")))mvc.perform(post("/api/v2/exercise/preview").contentType(MediaType.APPLICATION_JSON).content(input)).andExpect(status().isBadRequest());verifyNoInteractions(estimates);}
 @Test void confirmedCreateUsesOwnerReturns201Or200AndConflictCurrentPreview()throws Exception{var user=new User();user.setId(42L);when(current.requireGeneralUser(null)).thenReturn(user);String input=body().replace("\"durationMinutes\":50","\"durationMinutes\":50,\"calculationFingerprint\":\""+"a".repeat(64)+"\"");input=input.substring(0,input.length()-1)+",\"submissionId\":\""+id+"\",\"previewFingerprint\":\""+"b".repeat(64)+"\"}";var proof=new com.fitnutri.backend.submission.SubmissionReceiptV2Response(2,id,com.fitnutri.backend.submission.SubmissionOperation.EXERCISE_ENTRY_V2,java.time.Instant.EPOCH,false,List.of(),List.of());when(entries.createEntryV2(eq(42L),any())).thenReturn(proof,new com.fitnutri.backend.submission.SubmissionReceiptV2Response(2,id,proof.kind(),proof.committedAt(),true,List.of(),List.of()));mvc.perform(post("/api/v2/exercise/entries").contentType(MediaType.APPLICATION_JSON).content(input)).andExpect(status().isCreated()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(post("/api/v2/exercise/entries").contentType(MediaType.APPLICATION_JSON).content(input)).andExpect(status().isOk());var preview=new WorkoutEstimateService.Response(List.of(new WorkoutEstimateService.PeriodPreview(id,new BigDecimal("50"),"NO_WEIGHT",null,"a".repeat(64),"No dated weight")),new BigDecimal("50"),null,false,"b".repeat(64),"c".repeat(64));when(entries.createEntryV2(eq(42L),any())).thenThrow(new ExerciseCalculationChangedV2Exception(preview));mvc.perform(post("/api/v2/exercise/entries").contentType(MediaType.APPLICATION_JSON).content(input)).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("CALCULATION_CHANGED")).andExpect(jsonPath("$.currentPreview.periods[0].status").value("NO_WEIGHT")).andExpect(jsonPath("$.currentPreview.knownEnergyKj").value(org.hamcrest.Matchers.nullValue()));}

